from __future__ import annotations
import copy,random
STATES={'dashboard': ['feed', 'repositories', 'following', 'empty', 'new_repository', 'notifications'], 'repository': ['code', 'file_view', 'readme', 'releases', 'branch_picker', 'clone'], 'issues': ['open', 'closed', 'filtered', 'empty', 'labels', 'new_issue'], 'issue_detail': ['open', 'closed', 'editing', 'tasklist', 'assign', 'close_issue'], 'pull_requests': ['open', 'closed', 'drafts', 'empty', 'compare_branches', 'filters'], 'pull_request_detail': ['conversation', 'commits', 'files_changed', 'checks', 'review', 'merge'], 'actions': ['runs', 'running', 'failed', 'run_detail', 'dispatch', 'rerun'], 'projects': ['board', 'table', 'roadmap', 'empty', 'new_item', 'field_options'], 'code_search': ['code', 'repositories', 'users', 'no_results', 'advanced_filters', 'saved_search'], 'settings': ['general', 'collaborators', 'branches', 'notifications', 'delete_repository', 'add_secret']}
POPUPS={'rerun', 'clone', 'notifications', 'new_repository', 'delete_repository', 'labels', 'close_issue', 'field_options', 'branch_picker', 'assign', 'new_issue', 'filters', 'merge', 'new_item', 'advanced_filters', 'compare_branches', 'add_secret', 'saved_search', 'review', 'dispatch'}
NAV=[('dashboard','dashboard','Dashboard'),('repository','code','Repository'),('issues','error_outline','Issues'),('issue_detail','chat_bubble_outline','Issue'),('pull_requests','merge','Pull requests'),('pull_request_detail','difference','Pull request'),('actions','play_circle_outline','Actions'),('projects','view_kanban','Projects'),('code_search','search','Search'),('settings','settings','Settings')]
ISSUE_TITLES=['Improve keyboard navigation in the search dialog','Handle empty results in the file browser','Add theme preference to user settings','Document local development setup','Fix clipped toolbar on small screens','Add pagination to activity feed','Preserve filters when switching tabs','Improve error messages for failed requests','Update dependency lockfile','Support sorting by last updated','Add accessible labels to icon controls','Review caching for repository metadata']
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 issues=[{'number':142+i,'title':t,'author':['alex-dev','sam-code','taylor-ui'][i%3],'initials':['AM','SK','TR'][i%3],'label':['bug','enhancement','documentation'][i%3],'comments':random.randint(1,18),'status':'Closed' if i%4==0 else 'Open','task_done':i%3==0} for i,t in enumerate(ISSUE_TITLES)]
 pulls=[{'number':86+i,'title':t,'author':['alex-dev','sam-code','taylor-ui'][i%3],'status':['Open','Draft','Merged','Closed'][i%4],'checks':i%3!=0,'comments':random.randint(1,9),'branch':f'feature/update-{i+1}'} for i,t in enumerate(['Add responsive repository navigation','Fix empty state for search results','Refactor theme preference storage','Improve issue template accessibility','Update contribution instructions','Cache repository summary requests','Add project field sorting','Improve test fixtures'])]
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'navigation':NAV,'owner':'demo-org','repo':'interface-lab','viewer':{'name':'Alex Morgan','login':'alex-dev','initials':'AM'},'issues':issues,'issue':issues[1],'pulls':pulls,'pull':pulls[0],'files':[{'name':n,'icon':icon,'message':m,'age':age} for n,icon,m,age in [('src','folder','Improve repository navigation','2 hours ago'),('tests','folder','Add search fixtures','yesterday'),('docs','folder','Update getting started guide','3 days ago'),('.github','folder','Configure CI workflow','last week'),('.gitignore','description','Ignore build artifacts','last week'),('README.md','description','Document interface examples','3 days ago'),('package.json','description','Update project scripts','yesterday'),('LICENSE','description','Add example license','last month')]],'branches':['main','develop','feature/search','fix/toolbar','docs/getting-started'],'query':'repo:demo-org/interface-lab navigation','runs':[{'id':230+i,'name':['CI','Deploy preview','Code quality'][i%3],'title':['Improve repository navigation','Update documentation','Refactor search filters'][i%3],'status':['Success','Failure','In progress','Queued'][i%4],'branch':'main' if i%2==0 else 'feature/search','duration':['2m 14s','1m 42s','3m 05s'][i%3],'commit':f'demo{i:03d}a'} for i in range(10)],'commits':[{'sha':f'demo{i:03d}b','message':m,'author':'alex-dev'} for i,m in enumerate(['Add responsive navigation','Cover empty states','Update accessibility labels','Address review feedback'])],'contributions':[random.randint(0,4) for i in range(140)],'code':'export function filterItems(items, query) {\n  const normalized = query.trim().toLowerCase();\n  return items.filter((item) =>\n    item.name.toLowerCase().includes(normalized)\n  );\n}\n','sample_index':sample_index}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d['state']=state;d['popup_visible']=state in POPUPS
 if base['page']=='issues':
  if state=='closed':d['issues']=[i for i in d['issues'] if i['status']=='Closed']
  elif state=='filtered':d['issues']=[i for i in d['issues'] if i['label']=='bug' and i['status']=='Open']
  elif state=='open':d['issues']=[i for i in d['issues'] if i['status']=='Open']
 if base['page']=='pull_requests':
  if state=='closed':d['pulls']=[p for p in d['pulls'] if p['status'] in ['Closed','Merged']]
  elif state=='drafts':d['pulls']=[p for p in d['pulls'] if p['status']=='Draft']
  elif state=='open':d['pulls']=[p for p in d['pulls'] if p['status']=='Open']
 if state in ['empty','no_results']:d['issues']=[];d['pulls']=[];d['files']=[]
 if base['page']=='issue_detail' and state=='closed':d['issue']['status']='Closed'
 return d
